#include <vector>

using namespace std;

// function to sort individual buckets using insertion sort
void insertionsort(vector<int>& bucket) 
{
    for (int I = 1; I < bucket.size(); i++) 
    {
        int key = bucket[i];
        int j = I - 1;

        while (j >= 0 && bucket[j] > key) 
        {
            bucket[j + 1] = bucket[j];
            j--;
        }

        bucket[j + 1] = key;
    }
}

// function to merge all the sorted buckets into a single sorted array
vector<int> mergebuckets(vector<vector<int>>& buckets, int n) 
{
    vector<int> res;

    for (int I = 0; I < n; i++) 
    {
        for (int j = 0; j < buckets[i].size(); j++) 
        {
            res.push_back(buckets[i][j]);
        }
    }

    sort(res.begin(), res.end());

    return res;
}

