```
#!/usr/bin/perl

use strict;
use warnings;

my $filename = shift @ARGV;
my $n = shift @ARGV;

# Handle invalid filename or non-integer values of n
unless (-e $filename) {
    die "Error: File $filename does not exist.\n";
}
unless ($n =~ /^\d+$/) {
    die "Error: $n is not a valid integer.\n";
}

# Open the file for reading
open(my $fh, '<', $filename) or die "Error opening $filename: $!\n";

# Print the first n lines of the file to the console
my $line_count = 0;
while (<$fh>) {
    print;
    $line_count++;
    last if $line_count == $n;
}

# Close the file handle
close($fh);
