// Define a node structure for the linked list
struct Node {
    int data;
    Node* next;
};

// Function to add new nodes to the linked list
void addToLinkedList(Node** head, int data) {
    Node* newNode = new Node();
    newNode->data = data;
    newNode->next = *head;
    *head = newNode;
}

// Function to find the length of the linked list
int findLength(Node* head) {
    int count = 0;
    Node* curr = head;
    while (curr != NULL) {
        count++;
        curr = curr->next;
    }
    return count;
}

int main() {
    Node* head = NULL;
    int n, data;
    cout << "Enter the number of elements to be added to the linked list: ";
    cin >> n;
    for (int I = 0; I < n; i++) {
        cout << "Enter element " << i+1 << ": ";
        cin >> data;
        addToLinkedList(&head, data);
    }
