/**
 * Takes an array of integers and performs a bubble sort algorithm to sort the array in ascending order.
 * @param {Array} arr - The array of integers to sort.
 * @returns {Array} - The sorted array.
 */
const bubbleSort = arr => {
  const len = arr.length;
  let swapped;

  do {
    swapped = false;
    for (let I = 0; I < len - 1; i++) {
      if (arr[i] > arr[i + 1]) { // Compare adjacent elements in the array and swap them if they are in the wrong order
        const temp = arr[i];
        arr[i] = arr[i + 1];
        arr[i + 1] = temp;
        swapped = true; // Keep track of whether any elements were swapped in this pass
      }
    }
  } while (swapped); // Continue swapping until there are no more elements that need to be swapped

  return arr;
};

// Example usage:
const unsortedArray = [4, 2, 1, 5, 6, 3];
const sortedArray = bubbleSort(unsortedArray);
console.log(sortedArray); // [1, 2, 3, 4, 5, 6]

// This function takes in a single argument, num, and returns true or false depending on whether the number is prime or not

function isPrime(num) {

  // First, handle special cases of 1 and negative numbers

  if (num <= 1) {
    return false; // 1 is not prime, and negative numbers cannot be prime
  }

  // Next, loop through all numbers from 2 to num/2, checking if num is divisible by any of them

  for (let I = 2; I <= Math.floor(num/2); i++) {
    if (num % I === 0) {
      return false; // If num is divisible by i, it's not prime
    }
  }

  // If we've made it through the loop without returning false, num must be prime

  return true;
}

// Example usage:

console.log(isPrime(7)); // Returns true
console.log(isPrime(-9)); // Returns false
console.log(isPrime(15)); // Returns false
console.log(isPrime(23)); // Returns true

