  var sliderWidth = slideCount * slideWidth + (slideCount - 1) * slideMargin;

  $('.slider').css('width', sliderWidth);

  var currentSlide = 0;
  var slidePerPage = 4;
  var totalPages = Math.ceil(slideCount / slidePerPage);
  var visibleSlides = slidePerPage;

  $('.prev').click(function() {
    if (currentSlide > 0) {
      currentSlide--;
      $('.slider').animate({
        left: '+=' + (slideWidth + slideMargin)
      });
    }
  });

  $('.next').click(function() {
    if (currentSlide < totalPages - 1) {
      currentSlide++;
      $('.slider').animate({
        left: '-=' + (slideWidth + slideMargin)
      });
    }
  });

  $(window).on('resize', function() {
    sliderWidth = slideCount * slideWidth + (slideCount - 1) * slideMargin;
    $('.slider').css('width', sliderWidth);
  });

  $('.slider-container').on('swipeleft', function() {
    $('.next').trigger('click');
  });

  $('.slider-container').on('swiperight', function() {
    $('.prev').trigger('click');
  });
