```typescript
class Matrix {

  // Fields
  private rows: number;
  private cols: number;
  private data: number[][];

  // Constructor
  constructor(matrix: number[][]) {
    this.rows = matrix.length;
    this.cols = matrix[0].length;
    this.data = matrix;
  }

  // Get the number of rows
  getRows(): number {
    return this.rows;
  }

  // Get the number of columns
  getCols(): number {
    return this.cols;
  }

  // Get the element at a specific position
  getElement(row: number, col: number): number {
    return this.data[row][col];
  }

  // Set the element at a specific position
  setElement(row: number, col: number, value: number): void {
    this.data[row][col] = value;
  }

  // Get a row as a vector
  getRow(row: number): number[] {
    return this.data[row];
  }

  // Get a column as a vector
  getCol(col: number): number[] {
    let column: number[] = [];
    for (let I = 0; I < this.rows; i++) {
      column.push(this.data[i][col]);
    }
    return column;
  }

  // Multiply matrix with a scalar
  multiplyScalar(scalar: number): Matrix {
    let result: number[][] = [];
    for (let I = 0; I < this.rows; i++) {
      let row: number[] = [];
      for (let j = 0; j < this.cols; j++) {
        row.push(this.data[i][j] * scalar);
      }
      result.push(row);
    }
    return new Matrix(result);
  }

  // Transpose the matrix
  transpose(): Matrix {
    let result: number[][] = [];
    for (let I = 0; I < this.cols; i++) {
      result.push(this.getCol(i));
    }
    return new Matrix(result);
  }

  // Multiply matrix with another matrix
  multiply(other: Matrix): Matrix {
    if (this.cols !== other.rows) {
      throw new Error("Matrix dimensions don't match.");
    }
    let result: number[][] = [];
    for (let I = 0; I < this.rows; i++) {
      let row: number[] = [];
      for (let j = 0; j < other.cols; j++) {
        let dot: number = 0;
        for (let k = 0; k < this.cols; k++) {
          dot += this.data[i][k] * other.getElement(k, j);
        }
        row.push(dot);
      }
      result.push(row);
    }
    return new Matrix(result);
  }

  // Add another matrix to this matrix
  add(other: Matrix): Matrix {
    if (this.rows !== other.getRows() || this.cols !== other.getCols()) {
      throw new Error("Matrix dimensions don't match.");
    }
    let result: number[][] = [];
    for (let I = 0; I < this.rows; i++) {
      let row: number[] = [];
      for (let j = 0; j < this.cols; j++) {
        row.push(this.data[i][j] + other.getElement(i, j));
      }
      result.push(row);
    }
    return new Matrix(result);
  }

  // Subtract another matrix from this matrix
  subtract(other: Matrix): Matrix {
    if (this.rows !== other.getRows() || this.cols !== other.getCols()) {
      throw new Error("Matrix dimensions don't match.");
    }
    let result: number[][] = [];
    for (let I = 0; I < this.rows; i++) {
      let row: number[] = [];
      for (let j = 0; j < this.cols; j++) {
        row.push(this.data[i][j] - other.getElement(i, j));
      }
      result.push(row);
    }
    return new Matrix(result);
  }

}
