    var reorderLevel: Int
) {
    fun updateQuantity(newQuantity: Int) {
        quantity = newQuantity
    }
    fun checkStockLevel(): String {
        return if(quantity < reorderLevel) "Low" else "In stock"
    }

    override fun toString(): String {
        return "InventoryItem(id=$id, name='$name', category='$category', quantity=$quantity, unitPrice=$unitPrice, reorderLevel=$reorderLevel)"
    }
}
\end{lstlisting}

\section{Inventory Management System Class}

The next step is to define a class for the inventory management system that will hold a collection of inventory items, and methods for adding, updating, and removing items, processing customer orders, tracking deliveries, and generating reports.

\begin{lstlisting}[language=Kotlin]
class InventoryManagementSystem {
    private var inventoryItems: MutableList<InventoryItem> = mutableListOf()

    fun addInventoryItem(item: InventoryItem) {
        inventoryItems.add(item)
    }

    fun updateInventoryItem(item: InventoryItem) {
        val index = inventoryItems.indexOfFirst { it.id == item.id }
        if(index != -1) {
            inventoryItems[index] = item
        }
    }

    fun removeInventoryItem(id: Int) {
        inventoryItems.removeIf { it.id == id }
    }

    fun processOrder(item: InventoryItem, quantity: Int): Double {
        val index = inventoryItems.indexOfFirst { it.id == item.id }
        if(index != -1) {
            val availableQuantity = inventoryItems[index].quantity
            if(quantity > availableQuantity) {
                throw RuntimeException("Insufficient stock")
            } else {
                inventoryItems[index].updateQuantity(availableQuantity - quantity)
                return item.unitPrice * quantity
            }
        } else {
            throw RuntimeException("Item not found")
        }
    }

    fun trackDelivery(item: InventoryItem, quantity: Int) {
        val index = inventoryItems.indexOfFirst { it.id == item.id }
        if(index != -1) {
            inventoryItems[index].updateQuantity(inventoryItems[index].quantity + quantity)
        } else {
            throw RuntimeException("Item not found")
        }
    }

    fun generateReport(): String {
        var report = ""
        for(item in inventoryItems) {
            report += item.toString() + "\n"
        }
        return report
    }

    fun getInventoryItems(): MutableList<InventoryItem> {
        return inventoryItems
    }
}
\end{lstlisting}

