// maze generation function
generatemaze(int rows, int cols){
    // create 2d array to store maze
    int maze[rows][cols] = {0}; 

    // place starting point randomly 
    int startx = rand() % cols; 
    int starty = rand() % rows;
    maze[starty][startx] = 1;

    // generate the maze using depth-first search algorithm
    stack<int> stackx;
    stack<int> stacky;
    stackx.push(startx);
    stacky.push(starty);

    while(!stackx.empty()){
        int currentx = stackx.top();
        int currenty = stacky.top();
        stackx.pop();
        stacky.pop();

        // check each neighbor of current cell
        vector<pair<int,int>> neighbors;
        if(currentx > 1 && maze[currenty][currentx-2] == 0) {
            neighbors.push_back({currenty, currentx-2}); // left
        }
        if(currentx < cols-2 && maze[currenty][currentx+2] == 0) {
            neighbors.push_back({currenty, currentx+2}); // right
        }
        if(currenty > 1 && maze[currenty-2][currentx] == 0) {
            neighbors.push_back({currenty-2, currentx}); // up
        }
        if(currenty < rows-2 && maze[currenty+2][currentx] == 0) {
            neighbors.push_back({currenty+2, currentx}); // down
        }

        // if there are no unvisited neighbors, backtrack
        if(neighbors.empty()){
            continue;
        }

        // randomly choose a neighbor and carve a path to it
        int randidx = rand() % neighbors.size();
        pair<int,int> nextcell = neighbors[randidx];
        int nextx = nextcell.second;
        int nexty = nextcell.first;

        // remove wall between current cell and next cell
        if(nextx > currentx) {
            maze[currenty][currentx+1] = 1;
        }
        if(nextx < currentx) {
            maze[currenty][currentx-1] = 1;
        }
        if(nexty > currenty) {
            maze[currenty+1][currentx] = 1;
        }
        if(nexty < currenty) {
            maze[currenty-1][currentx] = 1;
        }

        // add next cell to stack
        stackx.push(nextx);
        stacky.push(nexty);
    }
    return maze;
}

